Y = {}

Y["world-cup-history"] = ("نهائيات صنعت الأسطورة", "<p>تحتفظ الذاكرة بنهائيات لا تُنسى. في 1950 خسرت البرازيل على أرضها أمام أوروغواي في «ماراكانازو». وفي 1966 سجّل الإنجليزي جيف هيرست ثلاثية في فوز إنجلترا 4-2 على ألمانيا الغربية بعد التمديد. وفي 1998 فازت فرنسا على البرازيل 3-0 في أول لقب لها على أرضها. وفي 2010 سجّل إنييستا هدف الفوز لإسبانيا أمام هولندا في الوقت الإضافي.</p><p>وفي نهائي 2014 خسرت الأرجنتين أمام ألمانيا 1-0 بعد التمديد، ثم عادت بعد ثماني سنوات لتفوز على فرنسا بركلات الترجيح بعد تعادل 3-3 في نهائي قطر 2022.</p>")

Y["offside-rule-explained"] = ("أخطاء شائعة في فهم التسلل", "<ul><li><strong>الحكم بموقع اللاعب وقت الاستلام:</strong> الموقع المعتبر هو لحظة خروج الكرة من قدم زميله، لا لحظة وصولها إليه.</li><li><strong>اعتبار التساوي تسللاً:</strong> إذا كان المهاجم على خط واحد مع المدافع الأخير فهو في وضع قانوني.</li><li><strong>نسيان موقع الكرة:</strong> اللاعب الذي يكون خلف الكرة لا يمكن أن يُحتسب متسللاً حتى لو تجاوز كل المدافعين.</li><li><strong>الخلط بين الوضع والمخالفة:</strong> قد يكون المهاجم في وضع تسلل ولا تُحتسب عليه مخالفة إن لم يشارك في اللعب.</li></ul><p>إذا ضبطت هذه النقاط الأربع، فستفهم أغلب القرارات التي تُحسم على الشاشات.</p>")

Y["var-explained"] = ("كيف تقرأ إشارات المراجعة؟", "<p>عندما يضع حكم الساحة يده على أذنه ويتوقف اللعب، فهو يتواصل مع غرفة الفيديو. وإذا رسم بيديه شكل مستطيل فهذا يعني أن المراجعة جارية أو أنه سيذهب إلى الشاشة الجانبية. وبعد انتهاء المراجعة يعلن قراره بإشارة واضحة: هدف، أو لا هدف، أو ركلة جزاء.</p><p>وفي البطولات الكبرى تُعرض على شاشات الملعب رسوم توضيحية للقطة، حتى يفهم الجمهور سبب القرار. هذه الشفافية جزء من تحسين صورة التقنية لدى المشجعين الذين اعتادوا على اللعب المتواصل.</p>")

Y["premier-league-beginners-guide"] = ("أندية وقصص صنعت الدوري", "<p>شهد الدوري هيمنة مانشستر يونايتد في سنواته الأولى، ثم موسم الذين لا يُقهرون لآرسنال عام 2004، ثم صعود تشيلسي بعد استثمارات كبيرة. وفاز ليفربول بأول لقب له في عصر البريميرليغ موسم 2019/2020، بعد انتظار طويل منذ آخر لقب له في الدرجة الأولى عام 1990. وسيطر مانشستر سيتي على اللقب لسنوات، وحقق أربعة ألقاب متتالية من موسم 2020/2021 حتى 2023/2024، وهو أمر لم يحدث من قبل في الكرة الإنجليزية.</p>")

Y["champions-league-new-format"] = ("تفاصيل صغيرة تهم المتابع", "<p>تُوزَّع الفرق في أربعة مستويات، يضم كل منها تسعة فرق. وعند تساوي النقاط في ترتيب مرحلة الدوري يُفصل أولاً بفارق الأهداف ثم بعدد الأهداف المسجلة. كما لا تحمل الجولة الأخيرة طابعاً شكلياً، فكل المباريات تُلعب في التوقيت نفسه وكل نتيجة قد تغيّر الترتيب بين مراكز التأهل المباشر والملحق وخروج الفرق.</p><p>وللمتابع الجديد نصيحة بسيطة: انظر إلى الترتيب الكامل قبل كل جولة، فالمراكز الثمانية الأولى هي هدف الكبار لتجنب مباريات الملحق المرهقة.</p>")

Y["el-clasico-history"] = ("نتائج خالدة", "<p>تحفل ذاكرة الكلاسيكو بنتائج كبيرة. فاز برشلونة على ريال مدريد 6-2 على ملعب سانتياغو برنابيو في مايو 2009 بقيادة غوارديولا، وفاز 5-0 على كامب نو في نوفمبر 2010. وفي المقابل عرف ريال مدريد انتصارات كبيرة على أرض برشلونة، وظلت المباراة تحمل معنى خاصاً حتى حين تتراجع مكانة أحد الفريقين في الدوري.</p>")

Y["messi-vs-ronaldo-debate"] = ("كيف تُقيّم اللاعبين بإنصاف؟", "<ul><li><strong>الاستمرارية:</strong> من حافظ على مستواه العالي لفترة أطول؟</li><li><strong>البطولات الكبرى:</strong> ماذا فعل كل منهما في كأس العالم والبطولات القارية؟</li><li><strong>المواسم الفردية الاستثنائية:</strong> من قدّم أرقاماً أعلى في مواسم الذروة؟</li><li><strong>الدور في الفريق:</strong> صناعة اللعب مقابل إنهاء الهجمات.</li><li><strong>التأقلم:</strong> القدرة على النجاح في أكثر من دوري وأسلوب.</li></ul><p>اختلاف الأولويات في هذه المعايير يفسّر لماذا ينتهي الجدل دائماً بدون إجماع.</p>")

Y["palestine-football-history"] = ("كيف تدعم الكرة الفلسطينية؟", "<p>يبدأ الدعم من متابعة مباريات المنتخب والأندية ومشاركتها، وتسليط الضوء على قصص اللاعبين الشباب. ويمكن دعم الأكاديميات المحلية التي تعمل في ظروف صعبة، والتعريف بالمواهب التي تبرز في الفئات العمرية. ويبقى الحضور الجماهيري، حيثما أمكن، أهم عامل لإبقاء الشغف حياً في الملاعب.</p>")

Y["famous-football-stadiums"] = ("ما الذي يصنع ملعباً أسطورياً؟", "<p>لا تُصنع أسطورة الملعب بالإسمنت وحده. فالتاريخ الذي شهدته أرضه، وقرب المدرجات من الملعب، وقدرة الجمهور على صناعة الصوت، وتقاليد ما قبل المباراة، كلها تتجمع لتصنع أجواء لا يمكن تقليدها بسهولة. لهذا تحاول الأندية عند تجديد ملاعبها الحفاظ على روح المكان وليس زيادة السعة فقط.</p>")

Y["football-formations-guide"] = ("نصائح لقراءة المباراة من المدرجات", "<ul><li>راقب ارتفاع خط الدفاع: هل يضغط عالياً أم يتراجع قرب منطقته؟</li><li>انظر إلى الأظهرة: هل يتقدمون مع الكرة أم يبقون خلفها؟</li><li>عدّ لاعبي الوسط: كثافة الوسط تحسم غالباً من يملك الكرة.</li><li>لاحظ لحظة فقدان الكرة: كيف يتحول الفريق من الهجوم إلى الدفاع؟</li></ul><p>بهذه الملاحظات الأربع ستفهم لماذا يفوز فريق بنتيجة لا تعكس مجرى اللعب أحياناً.</p>")

Y["ballon-dor-history"] = ("جدل الجائزة", "<p>لا تخلو أي نسخة من الجائزة من جدل. يتساءل البعض إن كانت تكافئ الأداء الفردي أم الألقاب الجماعية، ويختلفون حول توقيت التقييم في سنوات البطولات الكبرى، ويشككون أحياناً في معايير تصويت الصحفيين. وهذا الجدل نفسه يمنح الجائزة حضورها، ويجعل قائمة المرشحين تُناقش لأسابيع قبل الإعلان.</p>")

Y["africa-cup-of-nations-guide"] = ("تحديات التنظيم والمواعيد", "<p>تغيّر موعد البطولة أكثر من مرة. أُقيمت نسخة كوت ديفوار في يناير وفبراير 2024 بعد تأجيل سابق. وأُقيمت نسخة 2025 في المغرب بين ديسمبر 2025 ويناير 2026، وهي المرة الأولى التي تقام فيها في فترة أعياد رأس السنة، بسبب تعارض الموعد مع كأس العالم للأندية الموسّعة. ويعكس هذا حجم الضغط على الروزنامة الدولية للعبة.</p>")

Y["asian-cup-history"] = ("صعود المنتخبات الآسيوية عالمياً", "<p>برزت المنتخبات الآسيوية في كأس العالم بنتائج لافتة. فقد بلغت كوريا الجنوبية نصف نهائي 2002 على أرضها، وهو أفضل إنجاز آسيوي في تاريخ البطولة. وفي مونديال 2022 فازت السعودية على الأرجنتين 2-1، وتغلبت اليابان على ألمانيا وإسبانيا في مجموعتها. وتؤكد هذه النتائج أن الفجوة تضيق عاماً بعد عام.</p>")

Y["leicester-city-2016-miracle"] = ("دروس للأندية الصغيرة", "<p>اعتمد ليستر على سياسة استقطاب ذكية. تعاقد مع جيمي فاردي من فليتوود تاون في الدرجات الدنيا، ومع رياض محرز من لو هافر الفرنسي، ومع نغولو كانتي من كاين. لم يكن أي منهم نجماً حين وصل، لكن اختيارهم بعناية ووضعهم في دور واضح صنع الفارق. ويُستشهد بالتجربة كدليل على قوة الكشافة الجيدة والتخطيط في ناد بميزانية أصغر من منافسيه.</p>")

Y["laliga-guide"] = ("الأكاديميات ومدرسة اللعب", "<p>تشتهر الأندية الإسبانية بأكاديمياتها الكبرى. تخرّج من «لا ماسيا» في برشلونة لاعبون بارزون، وتعمل «لا فابريكا» في ريال مدريد بدور مماثل، ويمتلك أتلتيك بلباو مدرسة محلية خاصة. وهذا الاهتمام بتكوين اللاعب الشاب هو أحد أسباب هيمنة إسبانيا على الساحة الدولية في فترات كثيرة.</p>")

Y["pele-maradona"] = ("اختلاف الأسلوب", "<ul><li><strong>بيليه:</strong> مهاجم متكامل يجيد التسجيل بالقدمين والرأس، وتميّز بذكائه في التمركز.</li><li><strong>مارادونا:</strong> صانع ألعاب ومراوغ بقدمه اليسرى، يقود فريقه بالكرة وبالشخصية.</li></ul><p>ولا تكفي الأرقام وحدها لمقارنة لاعبين من زمنين مختلفين وبيئتين مختلفتين، لأن طبيعة اللعب والإعداد البدني والتحكيم تغيّرت كثيراً بينهما.</p>")

Y["womens-football-rise"] = ("التحديات المتبقية", "<p>ما زالت اللعبة تواجه تحديات في المساواة بالأجور والمرافق والتغطية الإعلامية والروزنامة. وكانت الاتحادات تتخذ خطوات في هذا الاتجاه، ومنها اتفاق اتحاد كرة القدم الأمريكي عام 2022 على المساواة في الأجور بين منتخبي الرجال والسيدات. وتبقى الخطوة التالية تحويل الحضور الجماهيري الاستثنائي في المباريات الكبرى إلى اعتياد يومي.</p>")

Y["football-fitness-program"] = ("جدول أسبوعي نموذجي", "<ul><li><strong>اليوم الأول:</strong> تحمّل.</li><li><strong>اليوم الثاني:</strong> راحة أو تمارين مرونة خفيفة.</li><li><strong>اليوم الثالث:</strong> سرعة.</li><li><strong>اليوم الرابع:</strong> راحة.</li><li><strong>اليوم الخامس:</strong> قوة.</li><li><strong>اليوم السادس:</strong> مباراة ودية أو تدريب بالكرة.</li><li><strong>اليوم السابع:</strong> راحة كاملة.</li></ul><p>عدّل الجدول بحسب مستواك ووقتك، ولا تتخط يوم الراحة.</p>")

Y["world-cup-2026-lessons"] = ("ماذا تعلّمنا من الصيغة الجديدة؟", "<p>أتاحت الصيغة الموسعة فرصة لمنتخبات جديدة، وزادت عدد المباريات والإيرادات والحضور. وأضافت دوراً إقصائياً جديداً هو دور الـ32. لكنها رفعت أيضاً عدد المباريات التي يخوضها المتوّج إلى ثماني مباريات، ما يزيد الحمل على اللاعبين. وما زال النقاش مفتوحاً حول توازن الجودة والتوسع.</p>")

Y["italian-catenaccio-history"] = ("ما وراء الدفاع", "<p>لا يقتصر ما قدمته إيطاليا على الدفاع. فمركز كوفيرتشانو لتدريب المدربين قرب فلورنسا يعد من أشهر مراكز التكوين التدريبي في العالم، ويعمل مدربون إيطاليون في أندية أوروبية وعالمية كثيرة. وقد أنتجت الكرة الإيطالية مدربين كباراً مثل كابيلو وأنشيلوتي وليبي، وساهمت في نقل ثقافة التنظيم التكتيكي إلى ملاعب العالم.</p>")
